        price = Vehicles[i].price,
        category = Vehicles[i].category,
        hash = hash,
        type = Vehicles[i].type,
        shop = Vehicles[i].shop
    }
    QBCore.Shared.VehicleHashes[hash] = QBCore.Shared.Vehicles[Vehicles[i].model]
end
